enum class V2XBehaviorState
{
  Cruise,
  Follow,
  Overtake,
  LowSpeedAvoidance,
  SafetyBrake,
};

const char * to_string(const V2XBehaviorState state)
{
  switch (state) {
    case V2XBehaviorState::Cruise:
      return "Cruise";
    case V2XBehaviorState::Follow:
      return "Follow";
    case V2XBehaviorState::Overtake:
      return "Overtake";
    case V2XBehaviorState::LowSpeedAvoidance:
      return "LowSpeedAvoidance";
    case V2XBehaviorState::SafetyBrake:
      return "SafetyBrake";
  }
  return "Unknown";
}

enum class OvertakeLinePhase
{
  Idle,
  FollowPrepare,
  ShiftOut,
  Pass,
  Return,
  Recovery,
};

enum class FollowPrepareCause
{
  Unspecified,
  SafetyBrake,
  DynamicMissionWait,
  TacticalRevalidation,
  RecoveryRetention,
};

enum class ReturnReacquirePolicy
{
  /// A newly available same-target/same-side corridor may cancel an early Return.
  SameTargetEarly,
  /// The tactical owner deliberately relinquished Pass; finish Return before
  /// evaluating the target as a new Mission.
  FinishReturn,
};

enum class V2XTrackingResetPolicy
{
  PreserveHistory,
  ClearHistory,
};

const char * to_string(const OvertakeLinePhase phase)
{
  switch (phase) {
    case OvertakeLinePhase::Idle:
      return "Idle";
    case OvertakeLinePhase::FollowPrepare:
      return "FollowPrepare";
    case OvertakeLinePhase::ShiftOut:
      return "ShiftOut";
    case OvertakeLinePhase::Pass:
      return "Pass";
    case OvertakeLinePhase::Return:
      return "Return";
    case OvertakeLinePhase::Recovery:
      return "Recovery";
  }
  return "Unknown";
}

const char * to_string(const FollowPrepareCause cause)
{
  switch (cause) {
    case FollowPrepareCause::Unspecified:
      return "Unspecified";
    case FollowPrepareCause::SafetyBrake:
      return "SafetyBrake";
    case FollowPrepareCause::DynamicMissionWait:
      return "DynamicMissionWait";
    case FollowPrepareCause::TacticalRevalidation:
      return "TacticalRevalidation";
    case FollowPrepareCause::RecoveryRetention:
      return "RecoveryRetention";
  }
  return "Unknown";
}

overtake_core::PausedExecutionOrigin paused_execution_origin(
  const OvertakeLinePhase phase)
{
  switch (phase) {
    case OvertakeLinePhase::ShiftOut:
      return overtake_core::PausedExecutionOrigin::ShiftOut;
    case OvertakeLinePhase::Pass:
      return overtake_core::PausedExecutionOrigin::Pass;
    case OvertakeLinePhase::Recovery:
      return overtake_core::PausedExecutionOrigin::Recovery;
    case OvertakeLinePhase::Idle:
    case OvertakeLinePhase::FollowPrepare:
    case OvertakeLinePhase::Return:
      return overtake_core::PausedExecutionOrigin::None;
  }
  return overtake_core::PausedExecutionOrigin::None;
}

int behavior_restriction_rank(const V2XBehaviorState state)
{
  switch (state) {
    case V2XBehaviorState::Cruise:
      return 0;
    case V2XBehaviorState::Overtake:
      return 1;
    case V2XBehaviorState::Follow:
      return 2;
    case V2XBehaviorState::LowSpeedAvoidance:
      return 3;
    case V2XBehaviorState::SafetyBrake:
      return 4;
  }
  return 0;
}

enum class FrontRiskLevel
{
  Clear,
  Follow,
  BrakePrepare,
  AvoidCandidate,
  EmergencyBrake,
};

const char * to_string(const FrontRiskLevel level)
{
  switch (level) {
    case FrontRiskLevel::Clear:
      return "Clear";
    case FrontRiskLevel::Follow:
      return "Follow";
    case FrontRiskLevel::BrakePrepare:
      return "BrakePrepare";
    case FrontRiskLevel::AvoidCandidate:
      return "AvoidCandidate";
    case FrontRiskLevel::EmergencyBrake:
      return "EmergencyBrake";
  }
  return "Unknown";
}

